1. "use strict";
2. 
3. const createError = require("../common/parser-create-error");
4. const { hasPragma } = require("./pragma");
5. const locFns = require("./loc");
6. const postprocess = require("./postprocess");
7. 
8. function babelOptions({ sourceType, extraPlugins = [] }) {
9.   return {
10.     sourceType,
11.     allowAwaitOutsideFunction: true,
12.     allowImportExportEverywhere: true,
13.     allowReturnOutsideFunction: true,
14.     allowSuperOutsideMethod: true,
15.     allowUndeclaredExports: true,
16.     errorRecovery: true,
17.     createParenthesizedExpressions: true,
18.     plugins: [
19.       // When adding a plugin, please add a test in `tests/js/babel-plugins`,
20.       // To remove plugins, remove it here and run `yarn test tests/js/babel-plugins` to verify
21. 
22.       "doExpressions",
23.       "classProperties",
24.       "exportDefaultFrom",
25.       "functionBind",
26.       "functionSent",
27.       "numericSeparator",
28.       "classPrivateProperties",
29.       "throwExpressions",
30.       "logicalAssignment",
31.       "classPrivateMethods",
32.       "v8intrinsic",
33.       "partialApplication",
34.       ["decorators", { decoratorsBeforeExport: false }],
35.       "privateIn",
36.       ["moduleAttributes", { version: "may-2020" }],
37.       ["recordAndTuple", { syntaxType: "hash" }],
38.       ...extraPlugins,
39.     ],
40.   };
41. }
42. 
43. function resolvePluginsConflict(
44.   condition,
45.   pluginCombinations,
46.   conflictPlugins
47. ) {
48.   if (!condition) {
49.     return pluginCombinations;
50.   }
51.   const combinations = [];
52.   for (const combination of pluginCombinations) {
53.     for (const plugin of conflictPlugins) {
54.       combinations.push([...combination, plugin]);
55.     }
56.   }
57.   return combinations;
58. }
59. 
60. function createParse(parseMethod, ...pluginCombinations) {
61.   return (text, parsers, opts) => {
62.     // Inline the require to avoid loading all the JS if we don't use it
63.     const babel = require("@babel/parser");
64. 
65.     const sourceType =
66.       opts && opts.__babelSourceType === "script" ? "script" : "module";
67. 
68.     let ast;
69.     try {
70.       const combinations = resolvePluginsConflict(
71.         text.includes("|>"),
72.         pluginCombinations,
73.         [
74.           ["pipelineOperator", { proposal: "smart" }],
75.           ["pipelineOperator", { proposal: "minimal" }],
76.           ["pipelineOperator", { proposal: "fsharp" }],
77.         ]
78.       );
79.       ast = tryCombinations(
80.         (options) => babel[parseMethod](text, options),
81.         combinations.map((extraPlugins) =>
82.           babelOptions({ sourceType, extraPlugins })
83.         )
84.       );
85.     } catch (error) {
86.       throw createError(
87.         // babel error prints (l:c) with cols that are zero indexed
88.         // so we need our custom error
89.         error.message.replace(/ \(.*\)/, ""),
90.         error.loc
91.           ? {
92.               start: {
93.                 line: error.loc.line,
94.                 column: error.loc.column + 1,
95.               },
96.             }
97.           : { start: { line: 0, column: 0 } }
98.       );
99.     }
100.     delete ast.tokens;
101.     return postprocess(ast, { ...opts, originalText: text });
102.   };
103. }
104. 
105. const parse = createParse("parse", ["jsx", "flow"]);
106. const parseFlow = createParse("parse", [
107.   "jsx",
108.   ["flow", { all: true, enums: true }],
109. ]);
110. const parseTypeScript = createParse(
111.   "parse",
112.   ["jsx", "typescript"],
113.   ["typescript"]
114. );
115. const parseExpression = createParse("parseExpression", ["jsx"]);
116. 
117. function tryCombinations(fn, combinations) {
118.   let error;
119.   for (let i = 0; i < combinations.length; i++) {
120.     try {
121.       return rethrowSomeRecoveredErrors(fn(combinations[i]));
122.     } catch (_error) {
123.       if (!error) {
124.         error = _error;
125.       }
126.     }
127.   }
128.   throw error;
129. }
130. 
131. function rethrowSomeRecoveredErrors(ast) {
132.   if (ast.errors) {
133.     for (const error of ast.errors) {
134.       if (
135.         typeof error.message === "string" &&
136.         (error.message.startsWith(
137.           // UnexpectedTypeAnnotation
138.           // https://github.com/babel/babel/blob/2f31ecf85d85cb100fa08d4d9a09de0fe4a117e4/packages/babel-parser/src/plugins/typescript/index.js#L88
139.           "Did not expect a type annotation here."
140.         ) ||
141.           error.message.startsWith(
142.             // ModuleAttributeDifferentFromType
143.             // https://github.com/babel/babel/blob/bda759ac3dce548f021ca24e9182b6e6f7c218e3/packages/babel-parser/src/parser/location.js#L99
144.             "The only accepted module attribute is `type`"
145.           ))
146.       ) {
147.         throw error;
148.       }
149.     }
150.   }
151.   return ast;
152. }
153. 
154. function parseJson(text, parsers, opts) {
155.   const ast = parseExpression(text, parsers, opts);
156. 
157.   ast.comments.forEach(assertJsonNode);
158.   assertJsonNode(ast);
159. 
160.   return ast;
161. }
162. 
163. function assertJsonNode(node, parent) {
164.   switch (node.type) {
165.     case "ArrayExpression":
166.       return node.elements.forEach(assertJsonChildNode);
167.     case "ObjectExpression":
168.       return node.properties.forEach(assertJsonChildNode);
169.     case "ObjectProperty":
170.       if (node.computed) {
171.         throw createJsonError("computed");
172.       }
173. 
174.       if (node.shorthand) {
175.         throw createJsonError("shorthand");
176.       }
177.       return [node.key, node.value].forEach(assertJsonChildNode);
178.     case "UnaryExpression":
